/**
 * Singleton PhysicsSpatialGrid instance for the physics worker.
 * Import this for most use cases.
 */
export const physicsSpatialGrid: PhysicsSpatialGrid;
/**
 * PhysicsSpatialGrid - Hash-based spatial partitioning for physics bodies.
 *
 * Provides efficient spatial queries for static and kinematic bodies.
 * Use the exported singleton `physicsSpatialGrid` for most cases.
 */
export class PhysicsSpatialGrid {
    _staticGrid: Map<any, any>;
    _kinematicGrid: Map<any, any>;
    _dynamicGrid: Map<any, any>;
    _staticBodyCells: Map<any, any>;
    _kinematicBodyCells: Map<any, any>;
    cellSize: number;
    enabled: boolean;
    _tempBox: any;
    _queryCells: Int32Array<ArrayBuffer>;
    _queryCellCount: number;
    _queryResults: any[];
    _dynamicQueryResults: Set<any>;
    _seenIndices: Uint8Array<ArrayBuffer>;
    _seenGeneration: number;
    _oversizedStatics: any[];
    _oversizedKinematics: any[];
    _maxCellsPerBody: number;
    /**
     * Configure grid parameters.
     *
     * @param {Object} config - Configuration object.
     * @param {number} [config.cellSize] - Size of each grid cell in world units.
     * @param {boolean} [config.enabled] - Enable/disable spatial grid.
     * @returns {PhysicsSpatialGrid} This instance for chaining.
     */
    set(config: {
        cellSize?: number;
        enabled?: boolean;
    }): PhysicsSpatialGrid;
    /**
     * Rebuild the spatial grid with all provided bodies.
     * Use this after changing cellSize to re-hash all bodies with the new cell size.
     *
     * @param {Object} bodies - Object containing arrays of bodies by type.
     * @param {Array} [bodies.static] - Array of static bodies to re-insert.
     * @param {Array} [bodies.kinematic] - Array of kinematic bodies to re-insert.
     * @returns {PhysicsSpatialGrid} This instance for chaining.
     */
    rebuild(bodies: {
        static?: any[];
        kinematic?: any[];
    }): PhysicsSpatialGrid;
    /**
     * Compute numeric hash from cell coordinates.
     * Uses prime multiplication for good distribution.
     *
     * @param {number} cx - Cell X coordinate.
     * @param {number} cy - Cell Y coordinate.
     * @param {number} cz - Cell Z coordinate.
     * @returns {number} Numeric cell hash.
     * @private
     */
    private _hashCell;
    /**
     * Get all cells that a bounding box overlaps.
     * Stores results in _queryCells and sets _queryCellCount.
     * Returns false if the bbox spans too many cells (oversized body).
     *
     * @param {THREE.Box3} bbox - Axis-aligned bounding box.
     * @param {number} [maxCells] - Maximum cells allowed (0 = no limit).
     * @returns {boolean} True if cells were computed, false if oversized.
     * @private
     */
    private _getCellsForBBox;
    /**
     * Insert a body into the spatial grid.
     *
     * @param {Object} body - Physics body with bvh.geometry.boundingBox.
     * @param {string} type - 'static' or 'kinematic'.
     */
    insert(body: any, type: string): void;
    /**
     * Remove a body from the spatial grid.
     *
     * @param {number} bodyIndex - Body index in physicsState.
     * @param {string} type - 'static' or 'kinematic'.
     */
    remove(bodyIndex: number, type: string): void;
    /**
     * Update a body's position in the grid (for kinematics that move).
     *
     * @param {Object} body - Physics body.
     * @param {string} type - 'kinematic' (statics don't move).
     */
    update(body: any, type: string): void;
    /**
     * Query bodies near a world position.
     *
     * @param {THREE.Vector3} position - Query center position.
     * @param {number} radius - Query radius in world units.
     * @param {string} type - 'static' or 'kinematic'.
     * @param {Array} [frustumFiltered] - Pre-filtered array from frustum culling.
     * @returns {Array} Array of nearby body references.
     */
    queryNearby(position: THREE.Vector3, radius: number, type: string, frustumFiltered?: any[]): any[];
    /**
     * Query nearby bodies using a bounding box directly.
     * Useful for navigation grid queries where the Y range differs from XZ.
     *
     * @param {THREE.Box3} bbox - Bounding box to query.
     * @param {string} type - 'static' or 'kinematic'.
     * @returns {Array} Array of nearby body references.
     */
    queryNearbyBox(bbox: THREE.Box3, type: string): any[];
    /**
     * Insert a dynamic body into the spatial grid using spherical bounds.
     * Called during subStep to build the dynamic layer for D↔D collision.
     *
     * @param {number} index - Body index in physicsState.
     * @param {number} x - World X position.
     * @param {number} y - World Y position.
     * @param {number} z - World Z position.
     * @param {number} radius - Bounding sphere radius (capsule radius).
     */
    insertDynamic(index: number, x: number, y: number, z: number, radius: number): void;
    /**
     * Query dynamic bodies near a world position.
     * Returns a Set of body indices for efficient deduplication.
     *
     * @param {number} x - Query center X.
     * @param {number} y - Query center Y.
     * @param {number} z - Query center Z.
     * @param {number} radius - Query radius in world units.
     * @returns {Set<number>} Set of nearby dynamic body indices.
     */
    queryDynamic(x: number, y: number, z: number, radius: number): Set<number>;
    /**
     * Clear the dynamic grid.
     * Called at the start of each subStep before rebuilding.
     */
    clearDynamic(): void;
    /**
     * Clear all entries from the grid.
     */
    clear(): void;
    /**
     * Get debug statistics.
     *
     * @returns {Object} Grid statistics including cell counts and body counts.
     */
    getStats(): any;
}
